#!/usr/bin/env python3
"""Actual local TCP/SQL gateway and identity tests, no Tor/native/production claim."""
from pathlib import Path
import argparse,hashlib,json,os,subprocess,xml.etree.ElementTree as ET
p=argparse.ArgumentParser();p.add_argument('--jdk',required=True,type=Path);p.add_argument('--deps',action='append',required=True,type=Path);p.add_argument('--out',required=True,type=Path);p.add_argument('--focused-client',action='store_true');a=p.parse_args();root=Path(__file__).resolve().parents[2];a.out.mkdir(parents=True,exist_ok=True);classes=a.out/'classes';classes.mkdir(exist_ok=True);jars=sorted({f.resolve() for d in a.deps for f in d.glob('*.jar')});cp=os.pathsep.join(map(str,jars));sources=[]
